import {placeOnBreadboard} from './mounting.js';
export const SPI_GPIO_EXAMPLES=[{id:'spi-gpio',name:'Uno · MCP23S17 SPI GPIO',tag:'16 GPIO · LED / buton / IRQ'}];
export const SPI_GPIO_SOURCES={'spi-gpio':`#include <SPI.h>
void writeReg(uint8_t a,uint8_t v){digitalWrite(10,LOW);SPI.transfer(0x40);SPI.transfer(a);SPI.transfer(v);digitalWrite(10,HIGH);}
uint8_t readReg(uint8_t a){digitalWrite(10,LOW);SPI.transfer(0x41);SPI.transfer(a);uint8_t v=SPI.transfer(0);digitalWrite(10,HIGH);return v;}
void setup(){Serial.begin(115200);pinMode(10,OUTPUT);digitalWrite(10,HIGH);pinMode(2,INPUT);SPI.begin();SPI.beginTransaction(SPISettings(1000000,MSBFIRST,SPI_MODE0));writeReg(0,0xfe);writeReg(0x0d,0x80);writeReg(0x05,0x80);}
void loop(){static uint8_t high=0;writeReg(0x14,(high^=1));uint8_t irq=digitalRead(2),flags=readReg(0x0f),gpio=readReg(0x13);Serial.print("SPI GPIO B=");Serial.print(gpio);Serial.print(" IRQ=");Serial.print(irq);Serial.print(" FLAGS=");Serial.print(flags);Serial.print(" ADC=");Serial.println(analogRead(A0));delay(200);}
`};
export function makeSPIGPIOProject(base,id){if(id!=='spi-gpio')return null;const p=structuredClone(base);p.model=id;p.name=SPI_GPIO_EXAMPLES[0].name;p.code=SPI_GPIO_SOURCES[id];delete p.firmware;const part=(type,id,params={},x=800,y=550)=>{const c={id,type,x,y,rotation:0,params};p.components.push(c);return c;},wire=(from,to,color='#14b8a6')=>p.wires.push({id:'sgpio'+p.wires.length,from,to,color,points:[]});const m=part('mcp23s17','module');placeOnBreadboard(p,m,'bb');part('resistor','limit',{ohms:330},840,555);part('led','led',{color:'red'},925,550);part('button','key',{pressed:false},925,420);for(const[a,b]of[['5V','VDD'],['GND.1','VSS'],['5V','RESET'],['D10','CS'],['D13','SCK'],['D11','SI'],['D12','SO'],['GND.1','A0'],['GND.1','A1'],['GND.1','A2'],['D2','INTB'],['A0','GPA0']])wire('uno:'+a,'module:'+b);wire('module:GPA0','limit:1');wire('limit:2','led:A','#ef4444');wire('led:K','uno:GND.1','#64748b');wire('module:GPB7','key:1');wire('key:2','uno:GND.1','#64748b');p.settings.probe='D13';p.settings.tracePins=['D11','D12','D2'];p.settings.measurement={positive:'module:GPA0',negative:'uno:GND.1',current:'led:i'};return p;}
